/**
 * Translates a food suggestion or meal string into the user's active language.
 * Uses exact match dictionary lookup, case-insensitive match, and dynamic regex token replacement.
 */
export function translateFoodSuggestion(suggestion: string | undefined, lang: string | undefined): string {
  if (!suggestion) return '';
  const cleanLang = (lang || 'en').split('-')[0].toLowerCase();
  if (cleanLang === 'en') return suggestion;

  const trimmed = suggestion.trim();
  if (!trimmed) return '';

  // Extract leading bullet or dash if present
  let prefix = '';
  let core = trimmed;
  const prefixMatch = trimmed.match(/^([·•\-\*]\s*)/);
  if (prefixMatch) {
    prefix = prefixMatch[1];
    core = trimmed.slice(prefix.length).trim();
  }

  const dict = FOOD_DICTIONARY[cleanLang] || FOOD_DICTIONARY[cleanLang === 'hg' ? 'hu' : cleanLang];
  if (dict) {
    // 1. Exact match
    if (dict[core]) return prefix + dict[core];

    // 2. Case-insensitive match
    const lowerCore = core.toLowerCase();
    const matchedKey = Object.keys(dict).find(k => k.toLowerCase() === lowerCore);
    if (matchedKey) return prefix + dict[matchedKey];
  }

  // 3. Dynamic token fallback for composite/unseen suggestions
  const tokens = COMMON_FOOD_TOKENS[cleanLang];
  if (tokens) {
    let result = core;
    // Sort tokens longest first to avoid partial overlap replacement
    const sortedTokens = Object.keys(tokens).sort((a, b) => b.length - a.length);
    for (const eng of sortedTokens) {
      const regex = new RegExp(`\\b${eng}\\b`, 'gi');
      result = result.replace(regex, tokens[eng]);
    }
    // Quantity replacement like x2, x3 -> localized
    if (cleanLang === 'sv') result = result.replace(/x(\d+)/gi, '($1 st)');
    else if (cleanLang === 'de') result = result.replace(/x(\d+)/gi, '($1 Stk.)');
    else if (cleanLang === 'fr') result = result.replace(/x(\d+)/gi, '($1)');
    else if (cleanLang === 'pt') result = result.replace(/x(\d+)/gi, '($1 un.)');
    else if (cleanLang === 'es') result = result.replace(/x(\d+)/gi, '($1 uds.)');
    else if (cleanLang === 'it') result = result.replace(/x(\d+)/gi, '($1)');
    else if (cleanLang === 'nl') result = result.replace(/x(\d+)/gi, '($1 st.)');
    else if (cleanLang === 'da' || cleanLang === 'no') result = result.replace(/x(\d+)/gi, '($1 stk.)');
    else if (cleanLang === 'fi') result = result.replace(/x(\d+)/gi, '($1 kpl)');
    else if (cleanLang === 'hu' || cleanLang === 'hg') result = result.replace(/x(\d+)/gi, '($1 db)');
    else if (cleanLang === 'pl') result = result.replace(/x(\d+)/gi, '($1 szt.)');
    else if (cleanLang === 'tr') result = result.replace(/x(\d+)/gi, '($1 adet)');
    else if (cleanLang === 'ro') result = result.replace(/x(\d+)/gi, '($1 buc.)');
    else if (cleanLang === 'el') result = result.replace(/x(\d+)/gi, '($1 τμχ)');
    else if (cleanLang === 'bg') result = result.replace(/x(\d+)/gi, '($1 бр.)');
    else if (cleanLang === 'lt') result = result.replace(/x(\d+)/gi, '($1 vnt.)');
    else if (cleanLang === 'lv') result = result.replace(/x(\d+)/gi, '($1 gab.)');

    return prefix + result;
  }

  return prefix + core;
}
